407: /* Used to pass pictures into the encoder, and to get picture data back out of
408:  * the encoder.  The input and output semantics are different */
409: typedef struct x265_picture
410: {
411:     /* presentation time stamp: user-specified, returned on output */
412:     int64_t pts;
413: 
414:     /* display time stamp: ignored on input, copied from reordered pts. Returned
415:      * on output */
416:     int64_t dts;
417: 
418:     int vbvEndFlag; // New flag for VBV end feature
419: 
420:     /* force quantizer for != X265_QP_AUTO */
421:     /* The value provided on input is returned with the same picture (POC) on
422:      * output */
423:     void*   userData;
424: 
425:     /* Must be specified on input pictures, the number of planes is determined
426:      * by the colorSpace value */
427:     void*   planes[4];
428: 
429:     /* Stride is the number of bytes between row starts */
430:     int     stride[4];
431: 
432:     /* Must be specified on input pictures. x265_picture_init() will set it to
433:      * the encoder's internal bit depth, but this field must describe the depth
434:      * of the input pictures. Must be between 8 and 16. Values larger than 8
435:      * imply 16bits per input sample. If input bit depth is larger than the
436:      * internal bit depth, the encoder will down-shift pixels. Input samples
437:      * larger than 8bits will be masked to internal bit depth. On output the
438:      * bitDepth will be the internal encoder bit depth */
439:     int     bitDepth;
440: 
441:     /* Must be specified on input pictures: X265_TYPE_AUTO or other.
442:      * x265_picture_init() sets this to auto, returned on output */
443:     int     sliceType;
444: 
445:     /* Ignored on input, set to picture count, returned on output */
446:     int     poc;
447: 
448:     /* Must be specified on input pictures: X265_CSP_I420 or other. It must
449:      * match the internal color space of the encoder. x265_picture_init() will
450:      * initialize this value to the internal color space */
451:     int     colorSpace;
452: 
453:     /* Force the slice base QP for this picture within the encoder. Set to 0
454:      * to allow the encoder to determine base QP */
455:     int     forceqp;
456: 
457:     /* If param.analysisLoad and param.analysisSave are disabled, this field is
458:      * ignored on input and output. Else the user must call x265_alloc_analysis_data()
459:      * to allocate analysis buffers for every picture passed to the encoder.
460:      *
461:      * On input when param.analysisLoad is enabled and analysisData
462:      * member pointers are valid, the encoder will use the data stored here to
463:      * reduce encoder work.
464:      *
465:      * On output when param.analysisSave is enabled and analysisData
466:      * member pointers are valid, the encoder will write output analysis into
467:      * this data structure */
468:     x265_analysis_data analysisData;
469: 
470:     /* An array of quantizer offsets to be applied to this image during encoding.
471:      * These are added on top of the decisions made by rateControl.
472:      * Adaptive quantization must be enabled to use this feature. These quantizer
473:      * offsets should be given for each 16x16 block (8x8 block, when qg-size is 8).
474:      * Behavior if quant offsets differ between encoding passes is undefined. */
475:     float            *quantOffsets;
476: 
477:     /* Frame level statistics */
478:     x265_frame_stats frameData;
479: 
480:     /* User defined SEI */
481:     x265_sei         userSEI;
482: 
483:     /* Ratecontrol statistics for collecting the ratecontrol information.
484:      * It is not used for collecting the last pass ratecontrol data in 
485:      * multi pass ratecontrol mode. */
486:     void*  rcData;
487: 
488:     size_t framesize;
489: 
490:     int    height;
491: 
492:     // pts is reordered in the order of encoding.
493:     int64_t reorderedPts;
494: 
495:     //Dolby Vision RPU metadata
496:     x265_dolby_vision_rpu rpu;
497: 
498:     int fieldNum;
499: 
500:     //SEI picture structure message
501:     uint32_t picStruct;
502: 
503:     int    width;
504: 
505:     int   layerID;
506:     int    format;
507: } x265_picture;
