519: /* CPU flags */
520: 
521: /* x86 */
522: #define X265_CPU_MMX             (1 << 0)
523: #define X265_CPU_MMX2            (1 << 1)  /* MMX2 aka MMXEXT aka ISSE */
524: #define X265_CPU_MMXEXT          X265_CPU_MMX2
525: #define X265_CPU_SSE             (1 << 2)
526: #define X265_CPU_SSE2            (1 << 3)
527: #define X265_CPU_LZCNT           (1 << 4)
528: #define X265_CPU_SSE3            (1 << 5)
529: #define X265_CPU_SSSE3           (1 << 6)
530: #define X265_CPU_SSE4            (1 << 7)  /* SSE4.1 */
531: #define X265_CPU_SSE42           (1 << 8)  /* SSE4.2 */
532: #define X265_CPU_AVX             (1 << 9)  /* Requires OS support even if YMM registers aren't used. */
533: #define X265_CPU_XOP             (1 << 10)  /* AMD XOP */
534: #define X265_CPU_FMA4            (1 << 11)  /* AMD FMA4 */
535: #define X265_CPU_FMA3            (1 << 12)  /* Intel FMA3 */
536: #define X265_CPU_BMI1            (1 << 13)  /* BMI1 */
537: #define X265_CPU_BMI2            (1 << 14)  /* BMI2 */
538: #define X265_CPU_AVX2            (1 << 15)  /* AVX2 */
539: #define X265_CPU_AVX512          (1 << 16)  /* AVX-512 {F, CD, BW, DQ, VL}, requires OS support */
540: /* x86 modifiers */
541: #define X265_CPU_CACHELINE_32    (1 << 17)  /* avoid memory loads that span the border between two cachelines */
542: #define X265_CPU_CACHELINE_64    (1 << 18)  /* 32/64 is the size of a cacheline in bytes */
543: #define X265_CPU_SSE2_IS_SLOW    (1 << 19)  /* avoid most SSE2 functions on Athlon64 */
544: #define X265_CPU_SSE2_IS_FAST    (1 << 20)  /* a few functions are only faster on Core2 and Phenom */
545: #define X265_CPU_SLOW_SHUFFLE    (1 << 21)  /* The Conroe has a slow shuffle unit (relative to overall SSE performance) */
546: #define X265_CPU_STACK_MOD4      (1 << 22)  /* if stack is only mod4 and not mod16 */
547: #define X265_CPU_SLOW_ATOM       (1 << 23)  /* The Atom is terrible: slow SSE unaligned loads, slow
548:                                              * SIMD multiplies, slow SIMD variable shifts, slow pshufb,
549:                                              * cacheline split penalties -- gather everything here that
550:                                              * isn't shared by other CPUs to avoid making half a dozen
551:                                              * new SLOW flags. */
552: #define X265_CPU_SLOW_PSHUFB     (1 << 24)  /* such as on the Intel Atom */
553: #define X265_CPU_SLOW_PALIGNR    (1 << 25)  /* such as on the AMD Bobcat */
554: 
555: /* ARM */
556: #define X265_CPU_ARMV6           (1 << 0)
557: #define X265_CPU_NEON            (1 << 1)   /* ARM NEON */
558: #define X265_CPU_FAST_NEON_MRC   (1 << 2)   /* Transfer from NEON to ARM register is fast (Cortex-A9) */
559: #define X265_CPU_SVE2            (1 << 3)   /* AArch64 SVE2 */
560: #define X265_CPU_SVE             (1 << 4)   /* AArch64 SVE */
561: #define X265_CPU_NEON_DOTPROD    (1 << 5)   /* AArch64 Neon DotProd */
562: #define X265_CPU_NEON_I8MM       (1 << 6)   /* AArch64 Neon I8MM */
563: #define X265_CPU_SVE2_BITPERM    (1 << 7)   /* AArch64 SVE2 BitPerm */
564: 
565: /* RISCV */
566: #define X265_CPU_RVV             (1 << 0)   /* RISCV vector */
567: #define X265_CPU_ZBB             (1 << 1)   /* RISCV zbb */
568: 
569: /* LOONGARCH */
570: #define X265_CPU_LSX             0x0000001
