1089: /* x265 input parameters
1090:  *
1091:  * For version safety you may use x265_param_alloc/free() to manage the
1092:  * allocation of x265_param instances, and x265_param_parse() to assign values
1093:  * by name.  By never dereferencing param fields in your own code you can treat
1094:  * x265_param as an opaque data structure */
1095: typedef struct x265_param
1096: {
1097:     /* x265_param_default() will auto-detect this cpu capability bitmap.  it is
1098:      * recommended to not change this value unless you know the cpu detection is
1099:      * somehow flawed on your target hardware. The asm function tables are
1100:      * process global, the first encoder configures them for all encoders */
1101:     int       cpuid;
1102:     /*== Parallelism Features ==*/
1103: 
1104:     /* Number of concurrently encoded frames between 1 and X265_MAX_FRAME_THREADS
1105:      * or 0 for auto-detection. By default x265 will use a number of frame
1106:      * threads empirically determined to be optimal for your CPU core count,
1107:      * between 2 and 6.  Using more than one frame thread causes motion search
1108:      * in the down direction to be clamped but otherwise encode behavior is
1109:      * unaffected. With CQP rate control the output bitstream is deterministic
1110:      * for all values of frameNumThreads greater than 1. All other forms of
1111:      * rate-control can be negatively impacted by increases to the number of
1112:      * frame threads because the extra concurrency adds uncertainty to the
1113:      * bitrate estimations. Frame parallelism is generally limited by the the
1114:      * is generally limited by the the number of CU rows
1115:      *
1116:      * When thread pools are used, each frame thread is assigned to a single
1117:      * pool and the frame thread itself is given the node affinity of its pool.
1118:      * But when no thread pools are used no node affinity is assigned. */
1119:     int       frameNumThreads;
1120: 
1121:     /* Comma seperated list of threads per NUMA node. If "none", then no worker
1122:      * pools are created and only frame parallelism is possible. If NULL or ""
1123:      * (default) x265 will use all available threads on each NUMA node.
1124:      *
1125:      * '+'  is a special value indicating all cores detected on the node
1126:      * '*'  is a special value indicating all cores detected on the node and all
1127:      *      remaining nodes.
1128:      * '-'  is a special value indicating no cores on the node, same as '0'
1129:      *
1130:      * example strings for a 4-node system:
1131:      *   ""        - default, unspecified, all numa nodes are used for thread pools
1132:      *   "*"       - same as default
1133:      *   "none"    - no thread pools are created, only frame parallelism possible
1134:      *   "-"       - same as "none"
1135:      *   "10"      - allocate one pool, using up to 10 cores on node 0
1136:      *   "-,+"     - allocate one pool, using all cores on node 1
1137:      *   "+,-,+"   - allocate two pools, using all cores on nodes 0 and 2
1138:      *   "+,-,+,-" - allocate two pools, using all cores on nodes 0 and 2
1139:      *   "-,*"     - allocate three pools, using all cores on nodes 1, 2 and 3
1140:      *   "8,8,8,8" - allocate four pools with up to 8 threads in each pool
1141:      *
1142:      * The total number of threads will be determined by the number of threads
1143:      * assigned to all nodes. The worker threads will each be given affinity for
1144:      * their node, they will not be allowed to migrate between nodes, but they
1145:      * will be allowed to move between CPU cores within their node.
1146:      *
1147:      * If the three pool features: bEnableWavefront, bDistributeModeAnalysis and
1148:      * bDistributeMotionEstimation are all disabled, then numaPools is ignored
1149:      * and no thread pools are created.
1150:      *
1151:      * If "none" is specified, then all three of the thread pool features are
1152:      * implicitly disabled.
1153:      *
1154:      * Multiple thread pools will be allocated for any NUMA node with more than
1155:      * 64 logical CPU cores. But any given thread pool will always use at most
1156:      * one NUMA node.
1157:      *
1158:      * Frame encoders are distributed between the available thread pools, and
1159:      * the encoder will never generate more thread pools than frameNumThreads */
1160:     char numaPools[X265_MAX_STRING_SIZE];
1161: 
1162:     /* Enable wavefront parallel processing, greatly increases parallelism for
1163:      * less than 1% compression efficiency loss. Requires a thread pool, enabled
1164:      * by default */
1165:     int       bEnableWavefront;
1166: 
1167:     /* Use multiple threads to measure CU mode costs. Recommended for many core
1168:      * CPUs. On RD levels less than 5, it may not offload enough work to warrant
1169:      * the overhead. It is useful with the slow preset since it has the
1170:      * rectangular predictions enabled. At RD level 5 and 6 (preset slower and
1171:      * below), this feature should be an unambiguous win if you have CPU
1172:      * cores available for work. Default disabled */
1173:     int       bDistributeModeAnalysis;
1174: 
1175:     /* Use multiple threads to perform motion estimation to (ME to one reference
1176:      * per thread). Recommended for many core CPUs. The more references the more
1177:      * motion searches there will be to distribute. This option is often not a
1178:      * win, particularly in video sequences with low motion. Default disabled */
1179:     int       bDistributeMotionEstimation;
1180: 
1181:     /* Use a dedicated threadpool to pre-process motion estimation. Evaluates all
1182:      * PU combinations for CTUs in parallel. Dependencies between CTUs in inter
1183:      * frames is broken to allow for more parallelism, and as result may cause
1184:      * drop in compression efficiency. Recommended for many core CPUs and when
1185:      * loss in compression efficiency is acceptable for speedup of encoding.
1186:      * Default disabled.
1187:      */
1188:     int       bThreadedME;
1189: 
1190:     /*== Logging Features ==*/
1191: 
1192:     /* Enable analysis and logging distribution of CUs. Now deprecated */
1193:     int       bLogCuStats;
1194: 
1195:     /* Enable the measurement and reporting of PSNR. Default is enabled */
1196:     int       bEnablePsnr;
1197: 
1198:     /* Enable the measurement and reporting of SSIM. Default is disabled */
1199:     int       bEnableSsim;
1200: 
