178: uint32_t cpu_detect(bool benableavx512 )
179: {
180: 
181:     uint32_t cpu = 0;
182:     uint32_t eax, ebx, ecx, edx;
183:     uint32_t vendor[4] = { 0 };
184:     uint32_t max_extended_cap, max_basic_cap;
185:     uint64_t xcr0 = 0;
186: 
187: #if !X86_64
188:     if (!PFX(cpu_cpuid_test)())
189:         return 0;
190: #endif
191: 
192:     PFX(cpu_cpuid)(0, &max_basic_cap, vendor + 0, vendor + 2, vendor + 1);
193:     if (max_basic_cap == 0)
194:         return 0;
195: 
196:     PFX(cpu_cpuid)(1, &eax, &ebx, &ecx, &edx);
197:     if (edx & 0x00800000)
198:         cpu |= X265_CPU_MMX;
199:     else
200:         return cpu;
201:     if (edx & 0x02000000)
202:         cpu |= X265_CPU_MMX2 | X265_CPU_SSE;
203:     if (edx & 0x04000000)
204:         cpu |= X265_CPU_SSE2;
205:     if (ecx & 0x00000001)
206:         cpu |= X265_CPU_SSE3;
207:     if (ecx & 0x00000200)
208:         cpu |= X265_CPU_SSSE3 | X265_CPU_SSE2_IS_FAST;
209:     if (ecx & 0x00080000)
210:         cpu |= X265_CPU_SSE4;
211:     if (ecx & 0x00100000)
212:         cpu |= X265_CPU_SSE42;
213: 
214:     if (ecx & 0x08000000) /* XGETBV supported and XSAVE enabled by OS */
215:     {
216:         /* Check for OS support */
217:         xcr0 = PFX(cpu_xgetbv)(0);
218:         if ((xcr0 & 0x6) == 0x6) /* XMM/YMM state */
219:         {
220:             if (ecx & 0x10000000)
221:             cpu |= X265_CPU_AVX;
222:             if (ecx & 0x00001000)
223:                 cpu |= X265_CPU_FMA3;
224:         }
225:     }
226: 
227:     if (max_basic_cap >= 7)
228:     {
229:         PFX(cpu_cpuid)(7, &eax, &ebx, &ecx, &edx);
230:         /* AVX2 requires OS support, but BMI1/2 don't. */
231:         if (ebx & 0x00000008)
232:             cpu |= X265_CPU_BMI1;
233:         if (ebx & 0x00000100)
234:             cpu |= X265_CPU_BMI2;
235: 
